Object.entries(copy).forEach(([language, dictionary]) => i18n.addResourceBundle(language, 'designSystemDemo', dictionary))

export function Demo() {
  const [language, setLanguage] = useState('ru')
  const [open, setOpen] = useState(false)
  const [tab, setTab] = useState(0)
  const [notice, setNotice] = useState(false)
  const t = copy[language]
  function changeLanguage(value) { setLanguage(value); i18n.changeLanguage(value); document.documentElement.lang = value }
  return <main className="ds-demo">
    <header className="ds-header"><div><h1>{t.title}</h1><p>{t.intro}</p></div><div className="ds-tools"><Select label={t.language} value={language} onChange={event => changeLanguage(event.target.value)} options={[{value:'ru',label:'Русский'},{value:'kk',label:'Қазақша'},{value:'en',label:'English'}]}/><ThemeToggle/></div></header>
    <p className="ds-glyphs">Әә Ғғ Ққ Ңң Өө Ұұ Үү Һһ Іі · Обучение · Learning <code>RU / KK / EN</code></p>
    <section><h2>{t.actions}</h2><div className="ds-row"><Button onClick={() => setOpen(true)}>{t.primary}</Button><Button variant="secondary" onClick={() => setNotice(true)}>{t.secondary}</Button><Button variant="ghost" onClick={() => setNotice(false)}>{t.ghost}</Button><Button variant="danger" onClick={() => setOpen(true)}>{t.danger}</Button><Button disabled>{t.disabled}</Button><Button disabled aria-busy="true">{t.loading}</Button></div>{notice && <Notice message={t.confirmed}/>}</section>
    <section><h2>{t.fields}</h2><div className="ds-grid"><div><Input key={language} label={t.name} defaultValue={t.example} aria-describedby="ds-valid"/><small id="ds-valid">{t.valid}</small></div><div><Input label={t.invalid} aria-invalid="true" aria-describedby="ds-invalid" required/><small className="error" id="ds-invalid">{t.validation}</small></div><Select label={t.select} options={[{value:'text',label:t.option}]}/><Input label={t.locked} disabled value={t.example} readOnly/></div></section>
    <section><h2>{t.surfaces}</h2><div className="ds-grid ds-surfaces">{['base','raised','inset'].map(kind => <Surface key={kind} className={`ds-surface v2-surface--${kind}`}><h3>{t[kind]}</h3><p>{t.surfaceText}</p></Surface>)}</div></section>
    <section><h2>{t.tabs}</h2><div className="ds-row" role="tablist" aria-label={t.tabs}>{[t.overview,t.details].map((label,index) => <Button key={index} role="tab" id={`ds-tab-${index}`} aria-selected={tab===index} aria-controls={`ds-panel-${index}`} tabIndex={tab===index?0:-1} variant={tab===index?'primary':'ghost'} onClick={() => setTab(index)} onKeyDown={event => { if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault(); const next=event.key==='Home'?0:event.key==='End'?1:1-index;setTab(next);document.getElementById(`ds-tab-${next}`).focus()} }}>{label}</Button>)}</div>{[t.overviewText,t.detailsText].map((text,index) => <div key={index} role="tabpanel" id={`ds-panel-${index}`} aria-labelledby={`ds-tab-${index}`} hidden={tab!==index} tabIndex={0}><p>{text}</p></div>)}</section>
    <section><h2>{t.states}</h2><div className="ds-row">{[['success','success'],['warning','pending'],['error','error'],['info','info']].map(([key,tone]) => <Badge key={key} tone={tone}>{t[key]}</Badge>)}</div><div className="ds-grid ds-feedback"><Notice message={t.successText}/><p className="v2-notice v2-notice--warning" role="status">{t.warningText}</p><Notice error={t.errorText}/><p className="v2-notice v2-notice--info" role="status">{t.infoText}</p></div><label className="ds-progress" htmlFor="ds-progress">{t.progress}<progress id="ds-progress" max="100" value="40">40%</progress></label><div className="ds-grid"><Surface className="ds-surface"><h3>{t.empty}</h3><p>{t.emptyText}</p></Surface><Surface className="ds-surface"><p role="status" aria-busy="true">{t.loading}</p></Surface><Surface className="ds-surface"><p className="error">{t.errorText}</p><Button variant="secondary" onClick={() => setNotice(true)}>{t.retry}</Button></Surface></div></section>
    <section><Button variant="secondary" onClick={() => setOpen(true)}>{t.dialog}</Button></section>
    {open && <Dialog labelledBy="ds-dialog-title" onClose={() => setOpen(false)}><h2 id="ds-dialog-title">{t.dialogTitle}</h2><p>{t.dialogText}</p><div className="ds-row"><Button variant="secondary" onClick={() => setOpen(false)}>{t.close}</Button><Button onClick={() => {setOpen(false);setNotice(true)}}>{t.confirm}</Button></div></Dialog>}
  </main>
}
createRoot(document.getElementById('root')).render(<ThemeProvider><Demo/></ThemeProvider>)
